import manifest from "./media-manifest.json";

// Client photos/videos live on Vercel Blob. The manifest is generated by
// scripts/upload-media.mjs; see README "Media".
export type Media = { url: string; w: number; h: number };
const all = manifest as Record<string, Media>;

export function media(key: string): Media {
  const m = all[key];
  if (!m) throw new Error(`Missing media "${key}". Run npm run media:upload.`);
  return m;
}

/** Video plus the poster frame generated next to it (foo.mp4 + foo.jpg). */
export const video = (base: string) => ({ src: media(`${base}.mp4`), poster: media(`${base}.jpg`) });

export const mediaIn = (folder: string) =>
  Object.keys(all).filter((k) => k.startsWith(`${folder}/`)).map(media);
